var n=`0107-pelekie-zirni-ar-speki`;var a=`world-0107`;var t=`LV`;var r=`northern-europe`;var s=4;var o=555;var g={en:`Pelēkie Zirņi ar Speķi`,ua:`Сірий горох зі шпиком`};var d={en:`A Latvian grey-pea-and-bacon classic adapted with dried green peas because grey peas are absent from the ingredient catalog.`,ua:`Латвійська класична страва із сірого гороху та бекону, адаптована із сухим зеленим горохом через відсутність сірого в каталозі.`};var l=[{en:`Rinse the dried peas and soak for about 8 hours in the refrigerator, then drain. Simmer in fresh water until tender, roughly 60 minutes. This recipe uses dried green peas because grey peas are missing from the catalog.`,ua:`Промийте сухий горох і замочіть приблизно на 8 годин у холодильнику, потім злийте воду. Відварюйте у свіжій воді до м’якості, орієнтовно 60 хвилин. У рецепті використано сухий зелений горох, бо сірого немає в каталозі.`,t:[`boiling`],m:540,i:[[`green-peas-dried`,400,`g`],[`water`,1600,`ml`],[`table-salt`,4,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`bacon`,240,`g`],[`yellow-onion`,210,`g`],[`sunflower-oil`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-black-pepper`,null,`to_taste`],[`parsley`,15,`g`]]}];var u={slug:n,id:a,country:`LV`,region:r,servings:4,minutes:555,title:g,text:d,steps:l};export{t as country,u as default,a as id,o as minutes,r as region,s as servings,n as slug,l as steps,d as text,g as title};